import { lazy, Suspense } from 'react'

import { Skeleton } from '@chakra-ui/react'

const BeadsItemsImpl = lazy(() => import('./BeadsItemsImpl'));


export default function BeadsItems() {
  return (
    <Suspense fallback={<ItemsSuspense />}>
      <BeadsItemsImpl />
    </Suspense>
  )
}


function ItemsSuspense() {
  return (
    <Skeleton w='100%' h='100%' />
  )
}
